package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var s string
	fmt.Fscan(in, &n, &s)

	sf, fs := 0, 0
	for i := 1; i < n; i++ {
		if s[i-1] == 'S' && s[i] == 'F' {
			sf++
		} else if s[i-1] == 'F' && s[i] == 'S' {
			fs++
		}
	}

	if sf > fs {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

